SELECT id, goal_id, user_id, title, description, priority, status, due_date,
       estimated_minutes, sort_order, ai_generated, completed_at, created_at, updated_at
FROM learning_task WHERE user_id = #{userId}
AND status = #{status}
ORDER BY due_date IS NULL, due_date, sort_order, created_at DESC

